  const winner=outcomes.findIndex(result=>result.status==="fulfilled"),attempt=attempts[winner];expect(await confirmPayment(f.payer,attempt.prepared.paymentId,attempt.input,attempt.command)).toEqual((outcomes[winner] as PromiseFulfilledResult<unknown>).value);
  const loser=attempts[1-winner];expect(await db.prepare("SELECT status,journal_id FROM finance_payments WHERE id=?").bind(loser.prepared.paymentId).first()).toEqual({status:"released",journal_id:null});expect(await db.prepare("SELECT match_status FROM finance_bank_transactions WHERE id=?").bind(loser.bankId).first("match_status")).toBe("unmatched");
